41	function LineBlock({ widget }: { widget: Extract<Widget, { kind: "line" }> }) {
42	  // Flatten series into rows keyed by x for recharts.
43	  const xs = widget.series[0]?.points.map((p) => p.x) ?? [];
44	  const data = xs.map((x, i) => {
45	    const row: Record<string, string | number> = { x };
46	    for (const s of widget.series) {
47	      row[s.name] = s.points[i]?.y ?? 0;
48	    }
49	    return row;
50	  });
51	  return (
52	    <ChartContainer className="h-64 w-full" config={{}}>
53	      <LineChart data={data} margin={{ left: 12, right: 12 }}>
54	        <CartesianGrid vertical={false} />
55	        <XAxis dataKey="x" tickLine={false} />
56	        <YAxis tickLine={false} width={36} />
57	        <ChartTooltip content={<ChartTooltipContent />} />
58	        {widget.series.map((s, i) => (
59	          <Line
60	            dataKey={s.name}
61	            dot={false}
62	            key={s.name}
63	            stroke={SERIES_COLORS[i % SERIES_COLORS.length]}
64	            strokeWidth={2}
65	          />
66	        ))}
67	      </LineChart>
68	    </ChartContainer>
69	  );
70	}
