72	function TableBlock({ widget }: { widget: TableWidget }) {
73	  const [desc, setDesc] = useState(true);
74	  const col = widget.sortableColumn ?? -1;
75	  const rows =
76	    col >= 0
77	      ? [...widget.rows].sort((a, b) => {
78	          const av = Number(a[col]);
79	          const bv = Number(b[col]);
80	          return desc ? bv - av : av - bv;
81	        })
82	      : widget.rows;
